-- Exact seven reading passages from user's EL099 Quiz2 Passages PDF (visual pages 3–9).
-- 44 multiple-choice questions and their answer letters copied from that illustrated answer bank.
-- Some illustrations offer paraphrased/unsupported questions; keep exam DRAFT for academic review.
WITH passages AS(
 SELECT value AS row FROM jsonb_array_elements($el099_reading$[{"n":1,"title":"Vacation Adventures","page":3,"body":"Going on vacation is a wonderful way to relax and unwind from the stresses of everyday life. Whether it's a trip to the beach, a visit to a new city, or a getaway to the countryside, vacations offer a chance to explore new places and create lasting memories. During a vacation, people can indulge in activities they enjoy, such as swimming, hiking, sightseeing, or simply lounging by the pool.\n\nIt's a time to disconnect from work and responsibilities and focus on having fun and rejuvenating the mind and body. Planning a vacation can be exciting, from choosing the destination to booking accommodations and activities. It's important to pack everything needed for a comfortable and enjoyable trip, including clothes, toiletries, and any necessary documents. While on vacation, it's also essential to stay safe and healthy by following local guidelines and taking precautions against potential risks.\n\nWhether traveling solo, with family, or friends, vacations offer a chance to bond and create special moments together. After returning from a vacation, people often feel refreshed, energized, and ready to tackle whatever comes their way. Moreover, exploring local cuisines and trying new foods can be a delightful part of the vacation experience. Sampling delicious dishes adds to the adventure and provides insight into the culture of the destination. Additionally, engaging in cultural activities, such as attending festivals or visiting historical sites, enriches the vacation experience and fosters a deeper appreciation for different traditions. In conclusion, vacations offer a multitude of opportunities for relaxation, exploration, and personal growth. By embracing new experiences, staying safe, and taking time to unwind, travelers can create cherished memories that last a lifetime.","questions":[{"n":1,"k":1,"prompt":"What is a vacation?","options":[{"label":"a","text":"A stressful experience"},{"label":"b","text":"A chance to relax and unwind"},{"label":"c","text":"A time to work and be busy"},{"label":"d","text":"A time to focus on responsibilities"}],"correct":"b"},{"n":2,"k":2,"prompt":"What activities can people do on vacation?","options":[{"label":"a","text":"Work and chores"},{"label":"b","text":"Cleaning and organizing"},{"label":"c","text":"Staying indoors all day"},{"label":"d","text":"Swimming, hiking, sightseeing, or lounging by the pool"}],"correct":"d"},{"n":3,"k":3,"prompt":"What should people do to stay safe and healthy on vacation?","options":[{"label":"a","text":"Ignoring local guidelines"},{"label":"b","text":"Taking precautions against potential risks"},{"label":"c","text":"Not paying attention to their surroundings"},{"label":"d","text":"Eating unhealthy food"}],"correct":"b"},{"n":4,"k":4,"prompt":"What should people do after returning from vacation?","options":[{"label":"a","text":"Feel tired and unmotivated"},{"label":"b","text":"Feel refreshed and energized"},{"label":"c","text":"Focus on work and responsibilities immediately"},{"label":"d","text":"Forget about the vacation"}],"correct":"b"},{"n":5,"k":5,"prompt":"The pronoun “their” in “ready to tackle whatever comes their way” refers to:","options":[{"label":"a","text":"Responsibilities"},{"label":"b","text":"Memories"},{"label":"c","text":"People"},{"label":"d","text":"Vacations"}],"correct":"c"},{"n":6,"k":6,"prompt":"What can people do during a vacation?","options":[{"label":"a","text":"Relax and unwind"},{"label":"b","text":"Worry about work and responsibilities"},{"label":"c","text":"Stay indoors and do nothing"},{"label":"d","text":"Complain about everything"}],"correct":"a"},{"n":7,"k":7,"prompt":"What feelings do people often have after returning from vacation?","options":[{"label":"a","text":"Refreshed, energized, and ready to tackle challenges"},{"label":"b","text":"Stressed and overwhelmed"},{"label":"c","text":"Tired and unmotivated"},{"label":"d","text":"Bored and lonely"}],"correct":"a"},{"n":8,"k":8,"prompt":"What does the phrase “local guidelines” mean?","options":[{"label":"a","text":"Activities"},{"label":"b","text":"Risks"},{"label":"c","text":"Trips"},{"label":"d","text":"Instructions and rules"}],"correct":"d"}]},{"n":2,"title":"Discovering Dubai","page":4,"body":"Visiting Dubai is a great experience filled with awe-inspiring attractions and vibrant cultural experiences. From the towering skyscrapers that dominate the skyline to the bustling souks and traditional markets, there is something for everyone to enjoy in this dynamic city. One of the must-visit destinations in Dubai is the iconic Burj Khalifa, the tallest building in the world, offering breathtaking views of the city from its observation decks. Another popular attraction is the Dubai Mall, a shopper's paradise with an array of luxury boutiques, entertainment options, and the mesmerizing Dubai Aquarium.\n\nFor those interested in delving into the city's rich heritage, a visit to the Dubai Museum in Al Fahidi Fort provides insight into the emirate's history and culture. Additionally, exploring the traditional neighborhoods of Bastakiya and Al Seef offers a glimpse into Dubai's past, with its winding alleyways, historic buildings, and charming cafes. Moreover, Dubai's vibrant nightlife scene is not to be missed, with many bars, clubs, and lounges offering entertainment and excitement well into the early hours. Whether enjoying cocktails with a view at a rooftop bar or dancing the night away at a trendy nightclub, Dubai has something for every nocturnal adventurer. Additionally, for those seeking relaxation and rejuvenation, Dubai boasts an array of luxurious spas and wellness retreats where visitors can indulge in pampering treatments and holistic therapies. Furthermore, Dubai's commitment to innovation and sustainability is evident in its impressive array of eco-friendly initiatives and green spaces. From solar-powered buildings to vast urban parks, the city is paving the way for a more sustainable future while preserving its natural beauty and biodiversity. Additionally, Dubai's dedication to cultural diversity is celebrated through its numerous festivals, events, and exhibitions showcasing the traditions and talents of people from around the world. Whether attending a cultural festival, art exhibition, or musical performance, visitors to Dubai can experience the richness and diversity of global culture right in the heart of the city.","questions":[{"n":9,"k":1,"prompt":"What is one of the must-visit destinations in Dubai?","options":[{"label":"a","text":"Dubai Mall"},{"label":"b","text":"Dubai Museum"},{"label":"c","text":"Burj Khalifa"},{"label":"d","text":"Bastakiya"}],"correct":"c"},{"n":10,"k":2,"prompt":"What is the Dubai Mall known for?","options":[{"label":"a","text":"Luxury boutiques"},{"label":"b","text":"Traditional markets"},{"label":"c","text":"Historic buildings"},{"label":"d","text":"Souks"}],"correct":"a"},{"n":11,"k":3,"prompt":"What is Dubai known for in terms of dining?","options":[{"label":"a","text":"Italian cuisine"},{"label":"b","text":"Michelin-starred restaurants"},{"label":"c","text":"French cuisine"},{"label":"d","text":"Local eateries"}],"correct":"b"},{"n":12,"k":4,"prompt":"What does the pronoun “it” refer to in the statement about exploring the traditional neighborhoods?","options":[{"label":"a","text":"A visit to Dubai Museum"},{"label":"b","text":"A visit to Dubai Mall"},{"label":"c","text":"A visit to Burj Khalifa"},{"label":"d","text":"A visit to Dubai Aquarium"}],"correct":"a"},{"n":13,"k":5,"prompt":"What is the traditional neighborhood of Al Seef known for?","options":[{"label":"a","text":"Luxury boutiques"},{"label":"b","text":"Historic buildings"},{"label":"c","text":"Modern skyscrapers"},{"label":"d","text":"Entertainment options"}],"correct":"b"},{"n":14,"k":6,"prompt":"What can visitors witness during a desert safari?","options":[{"label":"a","text":"Sunrise"},{"label":"b","text":"Snowfall"},{"label":"c","text":"Rain"},{"label":"d","text":"Sunset"}],"correct":"d"},{"n":15,"k":7,"prompt":"What type of experience does a visit to Dubai promise?","options":[{"label":"a","text":"Boring journey"},{"label":"b","text":"Forgettable"},{"label":"c","text":"Unforgettable journey"},{"label":"d","text":"Stressful journey"}],"correct":"c"},{"n":16,"k":8,"prompt":"What does the word “breathtaking” mean?","options":[{"label":"a","text":"Beautiful and impressive"},{"label":"b","text":"Frightening and scary"},{"label":"c","text":"Uninteresting and dull"},{"label":"d","text":"Horrible and unpleasant"}],"correct":"a"}]},{"n":3,"title":"The Importance of Writing","page":5,"body":"Writing plays a crucial role in communication and self-expression. It allows us to convey our thoughts, ideas, and emotions effectively, whether through essays, stories, or letters. One of the key benefits of writing is its ability to improve our language skills, including spelling, grammar, and vocabulary. By practicing writing regularly, we become more proficient in expressing ourselves clearly and accurately.\n\nAdditionally, writing helps to organize our thoughts and structure our arguments coherently, enhancing our critical thinking abilities. Moreover, writing provides a creative outlet for self-expression, allowing us to explore our imagination and creativity. Whether through fiction, poetry, or journaling, writing allows us to capture our experiences and insights in a meaningful way. Furthermore, writing is a valuable tool for documentation and record-keeping, enabling us to preserve important information and memories for future reference. In today's digital age, writing takes on new forms, such as blogging and social media posts, which provide opportunities for sharing ideas and connecting with others. Writing is an essential skill that empowers us to communicate effectively, think critically, and express ourselves authentically.\n\nMoreover, writing fosters empathy and understanding by allowing us to explore diverse perspectives and experiences. Through storytelling and narrative, we can step into the shoes of others, gaining insights into different cultures, backgrounds, and worldviews. Additionally, writing promotes self-reflection and personal growth, as we articulate our thoughts and feelings on paper, gaining clarity and insight into ourselves. Furthermore, writing serves as a tool for advocacy and social change, empowering individuals to raise awareness about important issues and inspire action.","questions":[{"n":17,"k":1,"prompt":"How does writing contribute to improving language skills?","options":[{"label":"a","text":"By discouraging vocabulary expansion"},{"label":"b","text":"By avoiding grammar rules"},{"label":"c","text":"By practicing spelling and grammar"},{"label":"d","text":"By limiting expression"}],"correct":"c"},{"n":18,"k":2,"prompt":"What benefit does writing offer for organizing thoughts?","options":[{"label":"a","text":"Creating confusion"},{"label":"b","text":"Enhancing critical thinking"},{"label":"c","text":"Disrupting logical flow"},{"label":"d","text":"Encouraging randomness"}],"correct":"b"},{"n":19,"k":3,"prompt":"What role does writing play in self-expression?","options":[{"label":"a","text":"Limiting creativity"},{"label":"b","text":"Avoiding personal insights"},{"label":"c","text":"Discouraging exploration of ideas"},{"label":"d","text":"Encouraging imagination"}],"correct":"d"},{"n":20,"k":4,"prompt":"What is one advantage of writing in today's digital age?","options":[{"label":"a","text":"Decreasing opportunities for sharing ideas"},{"label":"b","text":"Reducing connection with others"},{"label":"c","text":"Providing platforms for sharing ideas"},{"label":"d","text":"Limiting expression"}],"correct":"c"},{"n":21,"k":5,"prompt":"How does writing contribute to creative expression?","options":[{"label":"a","text":"By limiting imagination"},{"label":"b","text":"By discouraging exploration"},{"label":"c","text":"By providing a creative outlet"},{"label":"d","text":"By enforcing strict rules"}],"correct":"c"},{"n":22,"k":6,"prompt":"What purpose does writing serve in academic and professional settings?","options":[{"label":"a","text":"Creating confusion"},{"label":"b","text":"Enhancing communication"},{"label":"c","text":"Discouraging collaboration"},{"label":"d","text":"Avoiding documentation"}],"correct":"b"},{"n":23,"k":7,"prompt":"How does writing contribute to personal growth and development?","options":[{"label":"a","text":"By discouraging self-reflection"},{"label":"b","text":"By avoiding exploration of ideas"},{"label":"c","text":"By limiting creativity"},{"label":"d","text":"By promoting self-expression"}],"correct":"d"},{"n":24,"k":8,"prompt":"What advantage does writing offer in terms of memory retention?","options":[{"label":"a","text":"Limiting information recall"},{"label":"b","text":"Enhancing information preservation"},{"label":"c","text":"Encouraging forgetfulness"},{"label":"d","text":"Discouraging mental exercise"}],"correct":"b"}]},{"n":4,"title":"Discovering Joy","page":6,"body":"Engaging in hobbies is not merely a pastime; it's a journey of self-discovery that shapes our identity, contributing to personal growth and holistic well-being. The path to a fulfilling hobby begins with embracing novelty, recognizing the uniqueness of each individual, and understanding that diverse interests define us. Once a passionate pursuit is identified, it evolves into an integral part of life, bringing joy and a sense of purpose. The benefits of cultivating a hobby extend beyond leisure; they encompass enhanced time management, skill acquisition, and a profound impact on overall well-being.\n\nThe journey of developing a hobby, despite the time investment, is inherently rewarding. Exposure to diverse activities allows individuals to choose pursuits that resonate, be it crafts, sports, puzzles, or skill development. A hobby becomes not just a diversion but a passion, providing a sense of purpose and boosting confidence for tackling new challenges in both personal and professional spheres.\n\nHobbies, whether involving physical activities or not, play a crucial role in reducing stress and promoting better health. Taking a short break from routine work to indulge in a hobby not only rejuvenates the mind but also prepares individuals to face future challenges more effectively.","questions":[{"n":25,"k":1,"prompt":"What is underscored as the starting point for discovering a fulfilling hobby?","options":[{"label":"a","text":"Sticking to familiar activities"},{"label":"b","text":"Embracing trends"},{"label":"c","text":"Trying something new"},{"label":"d","text":"Engaging in isolated activities"}],"correct":"c"},{"n":26,"k":2,"prompt":"How does the passage highlight the transformative nature of hobbies on confidence?","options":[{"label":"a","text":"Through the simplicity of hobbies"},{"label":"b","text":"Via exposure to diverse activities"},{"label":"c","text":"With a brief engagement period"},{"label":"d","text":"By avoiding social circles"}],"correct":"b"},{"n":27,"k":3,"prompt":"What is the primary focus of a hobby, according to the passage?","options":[{"label":"a","text":"Serving as a mere diversion"},{"label":"b","text":"Being a passion"},{"label":"c","text":"Offering skill development only"},{"label":"d","text":"Encouraging isolation"}],"correct":"b"},{"n":28,"k":4,"prompt":"How does the passage describe the impact of hobbies on mental and physical health?","options":[{"label":"a","text":"Hobbies increase the risk of high blood pressure"},{"label":"b","text":"Hobbies contribute to higher depression rates"},{"label":"c","text":"Hobbies promote better health and reduce stress"},{"label":"d","text":"Hobbies have no impact on overall health"}],"correct":"c"},{"n":29,"k":5,"prompt":"How does the passage describe the social benefits of having a hobby?","options":[{"label":"a","text":"Hobbies lead to isolation from social connections"},{"label":"b","text":"Hobbies reduce overall social well-being"},{"label":"c","text":"Hobbies provide an opportunity to connect with like-minded individuals"},{"label":"d","text":"Hobbies solely contribute to online interactions"}],"correct":"c"}]},{"n":5,"title":"The Enchanted Bookshop","page":7,"body":"In the heart of the town, there was a small, welcoming bookshop named Whimsical Pages. The shop was unlike any other, with shelves that seemed to go on forever and books that whispered tales of magic to those who listened closely.\n\nOne day, a curious young girl named Emily discovered the bookshop. As she entered, the shopkeeper, an old man with twinkling eyes, greeted her warmly. He handed her a mysterious-looking book and said, \"This book has the power to transport you to different worlds. Choose wisely, and your adventure awaits.\"\n\nExcited, Emily opened the book and found herself in a bustling city of talking animals. She marveled at the sights and sounds, meeting quirky characters and having grand adventures. When she closed the book, she was back at the bookshop.\n\nThe old man smiled, \"You've experienced just one of the many stories this book holds. Each time you open it, a new adventure awaits.\"\n\nFrom that day forward, Emily visited Whimsical Pages often, exploring realms of fantasy, mystery, and wonder through the magical pages.","questions":[{"n":30,"k":1,"prompt":"What is unique about the bookshop “Whimsical Pages”?","options":[{"label":"a","text":"It only sells textbooks"},{"label":"b","text":"It has endless shelves and magical books"},{"label":"c","text":"It is closed on weekends"},{"label":"d","text":"It only sells fiction books"}],"correct":"b"},{"n":31,"k":2,"prompt":"What did the shopkeeper say about the mysterious-looking book?","options":[{"label":"a","text":"It's just a regular book"},{"label":"b","text":"It's a boring book"},{"label":"c","text":"It's not for sale"},{"label":"d","text":"It has the power to transport you to different worlds"}],"correct":"d"},{"n":32,"k":3,"prompt":"Where did Emily find herself when she opened the mysterious book?","options":[{"label":"a","text":"In a quiet library"},{"label":"b","text":"In a deserted desert"},{"label":"c","text":"In a bustling city of talking animals"},{"label":"d","text":"In a dark and spooky forest"}],"correct":"c"},{"n":33,"k":4,"prompt":"What did Emily experience in the different worlds of the book?","options":[{"label":"a","text":"Dull and uneventful moments"},{"label":"b","text":"Only scary adventures"},{"label":"c","text":"Grand adventures and quirky characters"},{"label":"d","text":"Sad and lonely situations"}],"correct":"c"},{"n":34,"k":5,"prompt":"How often did Emily visit Whimsical Pages after her first adventure?","options":[{"label":"a","text":"Rarely"},{"label":"b","text":"Never again"},{"label":"c","text":"Occasionally"},{"label":"d","text":"Often"}],"correct":"d"}]},{"n":6,"title":"The Magical Forest","page":8,"body":"Once upon a time, in a dense forest, there was a magical tree known as the Harmony Tree. It was believed that anyone who visited the tree and listened to its gentle rustling leaves could make a special wish. The tree had the power to make dreams come true.\n\nOne day, a young girl named Lily ventured into the forest in search of the magical tree. As she walked through the ancient trees and vibrant flowers, she felt a sense of wonder and excitement. Soon, she stumbled upon a clearing where the Harmony Tree stood tall and majestic.\n\nLily approached the tree, and as the wind whispered through its leaves, she closed her eyes and made a wish. She wished for happiness not only for herself but for everyone in the village. The tree responded with a soft glow, and she felt a warm and comforting energy surrounding her.\n\nOverjoyed, Lily returned to her village, and soon, a wave of kindness and happiness spread throughout the community. People were helping each other, and laughter echoed through the streets. The magic of the Harmony Tree had touched not only Lily's heart but the hearts of everyone around her.","questions":[{"n":35,"k":1,"prompt":"What is the special power of the Harmony Tree?","options":[{"label":"a","text":"It can control the weather"},{"label":"b","text":"It can grant wishes"},{"label":"c","text":"It can talk to animals"},{"label":"d","text":"It can make people invisible"}],"correct":"b"},{"n":36,"k":2,"prompt":"What did Lily wish for at the Harmony Tree?","options":[{"label":"a","text":"Wealth and fame"},{"label":"b","text":"Superpowers"},{"label":"c","text":"Happiness for everyone"},{"label":"d","text":"Endless adventures"}],"correct":"c"},{"n":37,"k":3,"prompt":"How did the tree respond to Lily's wish?","options":[{"label":"a","text":"It made a loud noise"},{"label":"b","text":"It glowed softly"},{"label":"c","text":"It dropped its leaves"},{"label":"d","text":"It disappeared into the forest"}],"correct":"b"},{"n":38,"k":4,"prompt":"What did Lily feel as she made her wish?","options":[{"label":"a","text":"Scared and nervous"},{"label":"b","text":"Sad and lonely"},{"label":"c","text":"Warm and comforting"},{"label":"d","text":"Tired and confused"}],"correct":"c"},{"n":39,"k":5,"prompt":"What happened in the village after Lily visited the Harmony Tree?","options":[{"label":"a","text":"Everyone left the village"},{"label":"b","text":"People stopped helping each other"},{"label":"c","text":"The village became quiet and empty"},{"label":"d","text":"A wave of kindness and happiness spread"}],"correct":"d"}]},{"n":7,"title":"Coffee's Surprising Health Benefits","page":9,"body":"If you are addicted to coffee, and doctors warn you to quit the habit, don't worry and just keep relishing the beverage, because it's not that bad after all! In fact, according to a new study, the steaming cup of Java can beat fruits and vegetables as the primary source of antioxidants. Some studies state that coffee is the number one source of antioxidants in American diet, and both caffeinated and decaf versions appear to provide similar antioxidant levels.\n\nAntioxidants in general have been linked to a number of potential health benefits, including protection against heart diseases and cancer, but Vinson, a dietitian, said that their benefits ultimately depend on how they are absorbed and utilized in the body.\n\nThe research says that coffee outranks popular antioxidant sources like tea, milk, chocolate and cranberries. Of all the foods and beverages studied, dates actually have the most antioxidants based solely on serving size, but since dates are not consumed anywhere near the level of coffee, the drink comes as the top source of antioxidants, Vinson said.\n\nBesides keeping you alert and awake, coffee has been linked to an increasing number of potential health benefits, including protection against liver and colon cancer, type 2 diabetes, and Parkinson's disease, according to some recently published studies. The researchers, however, advise that one should consume coffee in moderation, because it can make you jittery and cause stomach pains.","questions":[{"n":40,"k":1,"prompt":"............. is an important source of antioxidants in American diet.","options":[{"label":"a","text":"Tea"},{"label":"b","text":"Coffee"},{"label":"c","text":"Milk"},{"label":"d","text":"Chocolate"}],"correct":"b"},{"n":41,"k":2,"prompt":"The word which means the same as “nervous” is:","options":[{"label":"a","text":"Alert"},{"label":"b","text":"Awake"},{"label":"c","text":"Moderation"},{"label":"d","text":"Jittery"}],"correct":"d"},{"n":42,"k":3,"prompt":"According to dietitian Sandra Vinson, the benefits of coffee ultimately depend on:","options":[{"label":"a","text":"How it is relished"},{"label":"b","text":"How they are absorbed and utilized in the body"},{"label":"c","text":"How they are served and consumed"},{"label":"d","text":"Whether it keeps us alert and awake"}],"correct":"b"},{"n":43,"k":4,"prompt":"............. have the most antioxidants among all the food and beverages.","options":[{"label":"a","text":"Dates"},{"label":"b","text":"Cranberries"},{"label":"c","text":"Tea and milk"},{"label":"d","text":"Coffee"}],"correct":"a"},{"n":44,"k":5,"prompt":"Consumption of coffee in excess,","options":[{"label":"a","text":"Is a suggestion from doctors"},{"label":"b","text":"Doesn't call the utter need to quit it"},{"label":"c","text":"Provides the richest source of maximum antioxidants"},{"label":"d","text":"Will make one feel jittery and cause stomach pains"}],"correct":"d"}]}]$el099_reading$::jsonb)
), inserted_passages AS(
 INSERT INTO public.intensive_passages(id,course_id,title,body)
 SELECT md5('NUMO:EL099:Q2:PASSAGE:'||(row->>'n'))::uuid,
 (SELECT id FROM public.intensive_courses WHERE code='EL099'),row->>'title',row->>'body'
 FROM passages ON CONFLICT(id) DO NOTHING RETURNING id
), questions AS(
 SELECT p.row->>'n' AS passage_n,p.row->>'page' AS source_page,
        qq.value AS q
 FROM passages p CROSS JOIN LATERAL jsonb_array_elements(p.row->'questions') AS qq(value)
), inserted_questions AS(
 INSERT INTO public.intensive_questions
 (id,course_id,exam_category,skill,type,difficulty,prompt,passage_id,grading_mode,marks,reference_source,reference_unit,reference_page,tags)
 SELECT md5('NUMO:EL099:Q2:READING:'||(q->>'n'))::uuid,
 (SELECT id FROM public.intensive_courses WHERE code='EL099'),
 'QUIZ 2','Reading','MULTIPLE_CHOICE','MEDIUM',q->>'prompt',
 md5('NUMO:EL099:Q2:PASSAGE:'||passage_n)::uuid,'AUTO',1,
 'EL099 Quiz2 Passages PDF','Reading · Passage '||passage_n,source_page,
 ARRAY['EL099-Q2-READING','PASSAGE='||passage_n,'SOURCE_Q='||(q->>'k')]
 FROM questions WHERE EXISTS(SELECT 1 FROM inserted_passages p WHERE p.id=md5('NUMO:EL099:Q2:PASSAGE:'||passage_n)::uuid)
 ON CONFLICT(id) DO NOTHING RETURNING id
), inserted_options AS(
 INSERT INTO public.intensive_question_options(id,question_id,label,value,is_correct,position)
 SELECT md5('NUMO:EL099:Q2:READING:'||(x.q->>'n')||':OPTION:'||(o.value->>'label'))::uuid,
 iq.id,o.value->>'label',o.value->>'text',(o.value->>'label')=(x.q->>'correct'),ascii(o.value->>'label')-96
 FROM questions x JOIN inserted_questions iq ON iq.id=md5('NUMO:EL099:Q2:READING:'||(x.q->>'n'))::uuid
 CROSS JOIN LATERAL jsonb_array_elements(x.q->'options') AS o(value)
 ON CONFLICT(id) DO NOTHING RETURNING id
), links AS(
 INSERT INTO public.intensive_exam_questions(exam_id,section_id,question_id,marks,position)
 SELECT md5('NUMO:EL099:QUIZ2:THREE_SECTIONS')::uuid,
 md5('NUMO:EL099:QUIZ2:SECTION:2')::uuid,iq.id,1,(x.q->>'n')::int
 FROM questions x JOIN inserted_questions iq ON iq.id=md5('NUMO:EL099:Q2:READING:'||(x.q->>'n'))::uuid
 ON CONFLICT DO NOTHING RETURNING id
)
SELECT (SELECT COUNT(*) FROM inserted_passages) passages_added,
 (SELECT COUNT(*) FROM inserted_questions) questions_added,
 (SELECT COUNT(*) FROM inserted_options) choices_added,
 (SELECT COUNT(*) FROM links) exam_links_added;